args.sparql:
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX dbr: <http://dbpedia.org/resource/>

ASK WHERE {
  VALUES ?movie1 { dbr:Inauguration_of_the_Pleasure_Dome }
  VALUES ?movie2 { dbr:Texans_Never_Cry }

  VALUES ?p1 { dbo:country dbp:country }
  VALUES ?p2 { dbo:country dbp:country }

  ?movie1 ?p1 ?c1 .
  ?movie2 ?p2 ?c2 .

  FILTER(STR(?c1) = STR(?c2))
}

